// 25 Questões de Simulado Comentadas (ALM018)
const MPOS=[
[[0],"Segundo a FAO, as perdas de alimentos diferenciam-se do desperdício por:",["Ocorrerem no domicílio do consumidor por descarte de sobras no prato","Ocorrerem do campo ao transporte interestadual por precariedade logística e embalagens rudimentares","Representarem apenas a fração descartada em supermercados por validade vencida","Envolverem unicamente o apodrecimento de carnes de açougue"],1,"Perdas referem-se às etapas iniciais (campo, colheita, transporte); desperdício refere-se ao varejo e consumidor final."],
[[0],"Os quatro estádios fenológicos do fruto em ordem cronológica sucessiva são:",["Crescimento, formação, senescência e maturação","Formação, crescimento, maturação e senescência","Maturação, formação, senescência e hipertrofia","Formação, senescência, crescimento e maturação"],1,"O ciclo desdobra-se em 1) Formação, 2) Crescimento, 3) Maturação e 4) Senescência terminal."],
[[1],"Qual das seguintes alternativas reúne exclusivamente frutos CLIMATÉRICOS?",["Laranja, limão, uva e abacaxi","Banana, abacate, manga, mamão e tomate","Morango, melancia, carambola e cacau","Caju, amora, figo e tangerina"],1,"Banana, abacate, manga, mamão, tomate, maçã e pera continuam amadurecendo plenamente fora da planta."],
[[1],"Se um lote de morangos ou uvas for colhido verde na lavoura, o desfecho esperado na despensa é:",["Evolução para cor vermelha viva e elevação de doçura em 5 dias","Incapacidade de amadurecer, murchamento progressivo e apodrecimento ácido","Síntese autocatalítica de etileno e rápida queda da acidez","Conversão espontânea de celulose em sacarose livre"],1,"Frutos não-climatéricos não continuam o amadurecimento após a colheita; colhidos verdes, não ganham açúcar nem perdem acidez."],
[[1,3],"O armazenamento conjunto de mamões papaia maduros com caixas de alface e brócolis em câmara fria hermética provoca:",["Estabilização da coloração esmeralda das hortaliças folhosas","Amarelamento acelerado e destruição do brócolis por indução da enzima clorofilase pelo etileno dos mamões","Inibição completa da respiração mitocondrial das alfaces","Aumento do teor de vitamina C em todas as hortaliças"],1,"O etileno gasoso exalado pelos mamões climatéricos induz a transcrição acelerada da clorofilase nos folhosos sensíveis, amarelando-os em 24-48h."],
[[2],"A energia térmica liberada pela respiração celular aeróbica dos tecidos vegetais vivos colhidos denomina-se:",["Calor latente de fusão","Calor vital","Entalpia de caramelização","Calor de Maillard"],1,"Calor vital é a energia térmica metabólica gerada pela respiração mitocondrial que precisa ser retirada continuamente pelos sistemas de frio."],
[[2],"O que estabelece o coeficiente de temperatura Q10 na fisiologia pós-colheita?",["Que a taxa respiratória dobra a cada elevação de 100 °C","Que a cada redução de 10 °C na temperatura ambiente, a taxa respiratória decai de 2 a 3 vezes","Que a síntese de etileno zera em temperaturas acima de 10 °C","Que o fruto perde 10% do seu peso a cada 24 horas"],1,"O Q10 (2 a 3) indica que resfriar o vegetal diminui a velocidade das enzimas respiratórias de duas a três vezes a cada 10 °C a menos."],
[[2],"Em embalagens com atmosfera modificada de vegetais frescos, concentrações de oxigênio abaixo de 2% provocam:",["Aumento da vida de prateleira por mais de 5 anos","Anóxia mitocondrial com fermentação anaeróbica gerando etanol/acetaldeído e risco de Clostridium botulinum","Paralisação absoluta do calor vital sem perda de umidade","Aumento imediato de açúcares solúveis e vitamina C"],1,"O₂ < 2% força o tecido vivo à fermentação alcoólica com off-flavors pungentes e cria ambiente estritamente anaeróbico para o botulismo."],
[[3],"No Ciclo de Yang, a enzima limitante e regulatória chave da biossíntese de etileno é a:",["SAM-sintetase","ACC-sintase","ACC-oxidase","Pectinametilesterase"],1,"A ACC-sintase catalisa a clivagem de SAM em ACC, sendo a etapa limitante estimulada por injúrias mecânicas, calor e estresse."],
[[3],"A enzima terminal ACC-oxidase requer estritamente qual cossubstrato para clivar o ACC e liberar etileno?",["Monóxido de carbono (CO)","Oxigênio molecular (O₂)","Nitrogênio gasoso (N₂)","Íons de magnésio bivalentes"],1,"A ACC-oxidase exige estritamente oxigênio molecular (O₂) para converter ACC em etileno; na anóxia a produção de etileno cessa."],
[[3],"O 1-metilciclopropeno (1-MCP / SmartFresh) estende a conservação pós-colheita de maçãs porque:",["Oxida quimicamente o etileno livre presente na atmosfera da câmara","Liga-se irreversivelmente aos receptores proteicos de etileno da membrana vegetal, bloqueando sua ação","Destrói as reservas de amido impedindo que a fruta apodreça","Acidifica o citoplasma celular eliminando qualquer atividade mitocondrial"],1,"O 1-MCP atua como antagonista competitivo de altíssima afinidade sobre os receptores celulares de etileno, bloqueando o sinal hormonal."],
[[4],"O desverdecimento de frutos climatéricos durante a maturação decorre da ação de qual enzima inicial sobre a clorofila?",["Amilase","Clorofilase","Poligalacturonase","Lactase"],1,"A clorofilase hidrolisa a ligação éster clivando a cauda hidrofóbica de fitol da molécula de clorofila."],
[[4],"As enzimas primárias responsáveis pela hidrólise das pectinas da lamela média e amolecimento da polpa são:",["PME (pectinametilesterase) e PG (poligalacturonase)","Lipase e fosfolipase A2","Invertase e catalase","Peptidase e colagenase"],0,"A PME desesterifica os grupos metoxila e a PG hidrolisa as ligações glicosídicas da cadeia péctica, solubilizando a parede celular."],
[[4],"A sensação adstringente na boca ao comer um caqui ou banana verde desaparece na maturação porque:",["Os taninos são evaporados como gases voláteis","Os taninos monoméricos livres polimerizam-se em complexos insolúveis que deixam de precipitar a saliva","A saliva do consumidor produz mais cálcio para dissolver os fenólicos","Os ácidos orgânicos destroem os receptores de paladar da língua"],1,"Com o amadurecimento, os taninos solúveis polimerizam-se em estruturas condensadas insolúveis que não conseguem interagir com as mucinas salivares."],
[[5],"A enzima polifenoloxidase (PPO) é uma metaloenzima que possui em seu sítio catalítico íons de:",["Zinco (Zn²⁺)","Cobre (Cu²⁺)","Magnésio (Mg²⁺)","Ferro heme (Fe²⁺)"],1,"A PPO contém íons de cobre (Cu²⁺) em seu sítio ativo coordenados por resíduos de histidina."],
[[5],"Na célula vegetal íntegra e não lesionada, o escurecimento enzimático não ocorre porque:",["A PPO só é sintetizada após o cozimento da fruta","Existe separação física: a PPO fica nos plastídeos e os compostos fenólicos ficam no vacúolo aquoso","O oxigênio não consegue transpor a epiderme vegetal intacta","Os compostos fenólicos só se formam na presença de luz solar direta"],1,"A compartimentalização subcelular mantém a enzima (plastídeos) e os substratos (vacúolo) fisicamente isolados até que ocorra dano mecânico."],
[[5],"Espremer limão sobre o abacate fatiado combate o escurecimento enzimático através de dois mecanismos simultâneos:",["Adição de sal para criar pressão osmótica e elevação do pH para 8,0","Redução do pH para < 3,5 pelo ácido cítrico (inativando a PPO) e poder redutor da vitamina C (revertendo quinonas a difenóis)","Evaporação de toda a água livre superficial e oxidação das gorduras","Aumento da temperatura superficial e precipitação das proteínas da casca"],1,"O ácido cítrico joga o pH longe do ótimo neutro da PPO e o ácido ascórbico reduz as quinonas eletrofílicas de volta a difenóis incolores."],
[[6],"A Injúria pelo Frio (Chilling Injury) em produtos de origem tropical (como banana e mamão) manifesta-se em temperaturas de:",["Abaixo de -18 °C sob congelamento rápido","5 °C a 15 °C (acima do ponto crioscópico)","Exclusivamente acima de 40 °C sob calor intenso","Qualquer temperatura na presença de luz UV"],1,"Chilling Injury instala-se entre 5 °C e 15 °C em tecidos tropicais por colapso na fluidez da membrana lipídica celular."],
[[6],"Folhas de alface que sofrem congelamento acidental no fundo da geladeira tornam-se translúcidas e flácidas porque:",["A PPO evapora a clorofila dos cloroplastos","Grandes macrocristais de gelo laceram mecanicamente as paredes celulares e membranas, provocando sinérese total","O frio converte os lipídeos em vitamina E sólida","O cálcio da parede celular transforma-se em gás carbônico"],1,"Macrocristais de gelo perfuram e rompem a arquitetura de celulose e membranas; no descongelamento a água escorre e a turgidez colapsa."],
[[6],"A mancha preta necrótica achatada no pólo estilar do tomate (Blossom-End Rot - BER) é causada por:",["Infecção bacteriana transmitida por moscas brancas","Deficiência localizada de cálcio nos tecidos em rápido crescimento da ponta do fruto","Excesso de nitrogênio gasoso no solo arenoso","Queimadura por frio em câmaras refrigeradas"],1,"A podridão estilar é desordem nutricional provocada pela carência de cálcio, enfraquecendo a pectina parietal da lamela média."],
[[6],"Tubérculos de batata que ficam expostos à luz nas gôndolas de supermercado tornam-se perigosos para a saúde porque:",["Perdem toda a água por transpiração acelerada","Sintetizam clorofila e o glicoalcaloide termoestável solanina (inibidor tóxico da acetilcolinesterase)","Acumulam ácido lático e toxina botulínica na polpa","Transformam o amido em colesterol oxidado"],1,"A luz estimula a rota dos glicoalcaloides gerando solanina tóxica e amarga, que resiste à fervura e fritura culinárias."],
[[7],"A recomendação técnica de colher frutas e hortaliças no início da manhã visa primariamente:",["Aproveitar a menor densidade de oxigênio do ar atmosférico","Aproveitar o menor calor de campo e a máxima turgidez hídrica dos tecidos vegetais","Impedir a síntese de clorofila pela fotossíntese diurna","Garantir que os operários trabalhem sem protetor solar"],1,"A colheita matinal encontra os tecidos túrgidos e com menor calor acumulado, reduzindo a taxa respiratória inicial e estresse térmico."],
[[7],"A substituição de caixas de madeira ásperas por caixas plásticas higienizáveis com cantos arredondados na pós-colheita tem por objetivo:",["Aumentar o peso bruto transportado nos caminhões","Eliminar ferimentos mecânicos abrasivos que servem de porta de entrada para fitopatógenos e ativam etileno","Impedir a circulação de ar entre os produtos empilhados","Reduzir a umidade relativa do ar para 20%"],1,"Caixas de madeira provocam cortes e escoriações que ativam a ACC-sintase de estresse e facilitam infecções bacterianas e fúngicas."],
[[7],"Na etapa de centrifugação de saladas higienizadas prontas para o consumo, uma rotação excessivamente violenta provoca:",["Eliminação total de bactérias patogênicas por força mecânica","Ruptura mecânica dos tecidos foliares com extravasamento de seiva vacuolar e escurecimento enzimático por PPO","Aumento da vida de prateleira por mais de 30 dias na gôndola","Formação de camada protetora de ceras naturais nas folhas"],1,"Supercentrifugação rasga as células e expele a seiva vacuolar ácida, colocando fenóis em contato com a PPO e arruinando o frescor visual."],
[[7],"Bactérias psicrotróficas patogênicas que representam risco severo em hortaliças minimamente processadas sob refrigeração deficiente incluem:",["*Listeria monocytogenes* e *Aeromonas hydrophila*","*Streptococcus thermophilus* e *Lactobacillus bulgaricus*","*Saccharomyces cerevisiae* e leveduras selvagens","*Penicillium roqueforti* e fungos filamentosos"],0,"*Listeria monocytogenes* é psicrotrófica, multiplicando-se até mesmo em temperaturas de 4 °C a 8 °C em vegetais crus prontos para consumo."],
[[8],"Na fabricação de geleias tradicionais com pectina ATM (> 50% metoxilada), qual é a função conjunta do açúcar (60-65%) e do ácido (pH 3,0-3,4)?",["O açúcar alcaliniza a fruta e o ácido dissolve as fibras de celulose","O açúcar desidrata as cadeias pécticas reduzindo a aw, e o ácido neutraliza as cargas negativas (COO⁻) permitindo a formação da rede de gel","O açúcar fornece cálcio livre e o ácido atua apenas como conservante químico","Ambos servem exclusivamente para caramelizar a frutose a 180 °C"],1,"Na pectina ATM, o açúcar sequestra água e o pH ácido protona os grupos carboxila, impedindo a repulsão eletrostática entre as cadeias."],
[[8],"Ao analisar o rótulo de uma bebida de uva cuja lista de ingredientes inicia por 'Água potável, açúcar, suco concentrado de uva (30%), ácido cítrico e aroma idêntico ao natural', o nutricionista conclui que o produto é:",["Suco de uva integral puro","Polpa de fruta in natura","Néctar ou bebida adoçada de fruta, pois a lista segue ordem decrescente e água/açúcar predominam sobre a polpa","Vinho tinto desalcoolizado"],2,"A lista de ingredientes segue ordem decrescente de peso; suco integral é 100% fruta sem adição de água ou açúcar."]
];

// 10 Casos Práticos de Tecnologia Pós-Colheita
const CLPOS=[
[[0,7],"Produtor colhe alfaces ao meio-dia sob sol forte de 34 °C e acondiciona as caixas de madeira empilhadas em caminhão aberto sem lona. Na chegada à Ceasa, 45% do lote é descartado como lixo. Qual a explicação técnica?",["A carga sofreu desperdício comportamental decorrente de exigência estética do feirante","Ocorrência de severa perda preliminar: calor de campo excessivo disparou a respiração e transpiração, e a madeira feriu as folhas ativando PPO","As alfaces sofreram freezing injury por choque térmico com o vento da rodovia","A radiação solar destruiu o magnésio da clorofila desintegrando o tecido"],1,"Colheita sob calor extremo maximizou a perda de água; as caixas de madeira feriram as folhas e a ausência de refrigeração causou perda precoce de 45% da carga."],
[[1,3],"Comprador adquire caixas de mamão papaia semi-verdes e armazena na mesma câmara fria hermética junto com caixas de brócolis fresco e alface. Dois dias depois, o brócolis está completamente amarelo e murcho. O que causou o prejuízo?",["O brócolis congelou devido ao contato com o ar seco da câmara","O etileno gasoso exalado pelos mamões em climatério induziu a expressão acelerada da enzima clorofilase nas folhas, degradando a clorofila","O mamão absorveu todo o oxigênio da sala deixando as hortaliças em fermentação alcoólica","A água da alface evaporou e condensou sobre o brócolis provocando podridão bacteriana"],1,"O etileno emitido pelos frutos climatéricos em amadurecimento ativo atua como hormônio senescente em tecidos verdes sensíveis, ativando a clorofilase."],
[[2],"Operador de câmara hermética de maçãs desliga os lavadores de CO2 e os compressores para economizar energia no final de semana. Na segunda-feira, a temperatura subiu para 18 °C e o CO2 atingiu 14%. As maçãs apresentaram polpa marrom e consistência aquosa. Qual a etiologia?",["Ação de fungos do gênero Penicillium que proliferaram pelo calor","O acúmulo de calor vital acelerou o metabolismo e o CO2 em concentração citotóxica (> 10%) desintegrou biomembranas causando necrose interna","As maçãs sofreram chilling injury por excesso de dióxido de carbono dissolvido","Ocorrência de fotoxidação das ceras cuticulares na ausência de ventilação"],1,"Sem remoção do calor vital e lavagem de gases, o CO2 ultrapassou os níveis toleráveis (citotóxico acima de 5-10%), provocando colapso de membranas e necrose da polpa."],
[[2,3],"Indústria embala fatias de manga fresca em filme plástico totalmente impermeável a gases e sem perfuração a 20 °C. Após 48h, a embalagem estufa e o produto exala cheiro característico de álcool e vinagre. Qual a rota metabólica envolvida?",["Respiração aeróbica acelerada com acúmulo excessivo de calor vital","Anóxia tecidual (O2 < 1%) forçando as células vegetais à fermentação anaeróbica alcoólica e lática com liberação de etanol e acetaldeído","Ação da polifenoloxidase convertendo açúcares em melaninas gasosas","Hidrólise do amido em ácido ascórbico que fermentou no suco da manga"],1,"Sem permeabilidade gasosa, o oxigênio foi totalmente consumido; as células vegetais migraram para a via fermentativa anaeróbica, gerando off-flavors pungentes."],
[[3],"Produtor de maçãs aplica 1-MCP gasoso (SmartFresh) na câmara frigorífica e consegue comercializar os frutos 8 meses depois com firmeza de polpa idêntica à da colheita. Qual foi o alvo molecular da intervenção?",["Os receptores proteicos de etileno da membrana celular vegetal, aos quais o 1-MCP se ligou irreversivelmente bloqueando a sinalização hormonal","A enzima polifenoloxidase, cujos íons de cobre foram quelados pelo gás","As mitocôndrias da fruta, que foram permanentemente destruídas pelo produto","A parede de celulose, que foi impermeabilizada com uma camada sintética de cera"],0,"O 1-MCP atua como inibidor competitivo irreversível dos receptores de etileno, impedindo que o fitormônio ative a transcrição de pectinases e amilases."],
[[4,5],"Cozinheira rala maçãs cruas e observa escurecimento marrom escuro em menos de 3 minutos. Em outro lote, as fatias são mergulhadas por 2 minutos em água fervente a 90 °C antes de ralar, mantendo a coloração clara. O que explica o resultado?",["A água fervente dissolveu todos os compostos fenólicos da fruta","O calor úmido superior a 70 °C desnaturou irreversivelmente a enzima polifenoloxidase (PPO), impedindo a oxidação catalítica dos fenóis","O oxigênio da água fervente reagiu com as quinonas transformando-as em licopeno incolor","A fervura eliminou as bactérias que produziam o pigmento marrom"],1,"A PPO é uma proteína catalítica que sofre desnaturação térmica irreversível em temperaturas superiores a 70 °C a 80 °C (princípio do branqueamento)."],
[[5],"Restaurante mexicano prepara guacamole de abacate amassado e nota que a adição generosa de suco de limão fresco e filme plástico colado à superfície preserva a cor esmeralda por 24h. Quais os princípios físico-químicos atuantes?",["O limão alcaliniza a polpa e o plástico atrai o oxigênio para fora da tigela","O ácido cítrico reduz o pH para < 3,5, a vitamina C reduz quinonas a difenóis e o plástico exclui fisicamente o oxigênio atmosférico","O limão estimula a síntese de clorofila nova e o plástico aquece o purê","O ácido ascórbico hidrolisa os lipídeos do abacate transformando-os em fitoesteróis incolores"],1,"Combinação perfeita: inativação enzimática por acidificação (ácido cítrico), reversão química redutora (vitamina C) e exclusão física do cossubstrato O₂ pelo filme colado."],
[[6],"Consumidor compra bananas nanicas perfeitas na feira e decide guardá-las na gaveta do refrigerador a 4 °C para não amadurecerem rápido. No dia seguinte, as cascas estão pretas acinzentadas e a polpa perdeu a consistência normal. O que aconteceu?",["As bananas sofreram freezing injury com formação de macrocristais de gelo lacerantes","Instalou-se a Injúria pelo Frio (Chilling Injury): a temperatura abaixo de 12 °C enrijeceu os lipídeos de membrana, extravasando a PPO sobre os fenóis da casca","O frio da geladeira atraiu bactérias anaeróbicas que digeriram a clorofila","A casca da banana perdeu água por osmose reversa contra o ar seco da geladeira"],1,"A banana é fruto tropical com temperatura crítica de segurança em torno de 13 °C; abaixo de 10 °C sofre colapso de membranas por chilling injury."],
[[6],"Agricultor constata que 30% dos seus tomates apresentam uma mancha preta achatada e necrótica no fundo (pólo estilar) e aplica fungicida na lavoura sem sucesso. Ao consultar um agrônomo, descobre que a causa é nutricional. Qual o mecanismo?",["A mancha é queimadura solar por ausência de folhas protetoras","Deficiência de cálcio no ápice distal do fruto que comprometeu a síntese de pectatos de cálcio na lamela média da parede celular","Excesso de fósforo no solo que insolubilizou o ferro da clorofila","Falta de boro que impediu a absorção de nitrogênio radicular"],1,"A podridão estilar (BER) decorre da carência de cálcio, elemento imóvel que falha em chegar ao ápice do fruto em crescimento rápido, enfraquecendo a lamela média."],
[[7],"Planta industrial de saladas 'fresh-cut' substitui centrífuga de alta rotação por equipamento com variador de frequência regulado para rotação branda. O teste sensorial após 5 dias na gôndola revelou bordas foliares sem manchas escuras e ausência de líquido no fundo do saco. Qual o mérito do ajuste?",["A rotação branda esterilizou a alface por choque térmico","Removeu eficazmente a água livre de lavagem sem romper as paredes celulares nem extravasar a seiva vacuolar interna, contendo a PPO","Permitiu que as folhas sintetizassem nova cutícula de cera protetora","Converteu a pectina solúvel em celulose cristalina rígida"],1,"A rotação calibrada atinge o equilíbrio perfeito: elimina a umidade superficial que favoreceria fungos, sem aplicar força centrífuga destrutiva que rasgaria os tecidos."]
];

